        "ult": "대상 지정 불가 상태가 되어 120 거리를 돌진하며 돌진하는 궤적 내에 있는 각 적으로부터 300 + 주문력의 {Coef}% 만큼 체력을 흡수하고, 200 + 주문력의 {DamageCoef}% 만큼의 마법 피해를 입힌다."
